Reviewed-by: Dragos Tatulea <dtatulea@nvidia.com>
Reviewed-by: Tariq Toukan <tariqt@nvidia.com>
Signed-off-by: Gal Pressman <gal@nvidia.com>
Link: https://patch.msgid.link/20251208121901.3203692-1-gal@nvidia.com
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
The number of statistics can change between the three ioctl calls (ETHTOOL_GSSET_INFO for size, ETHTOOL_GSTRINGS for names, ETHTOOL_GSTATS for values) due to device reconfiguration, causing userspace's buffer allocation to be incorrect. If the number of stats increases, the kernel writes beyond the allocated buffer, resulting in a buffer overflow. The race window exists between the separate ioctl calls when RTNL lock is released.

Here is the patch:

 static int ethtool_get_strings(struct net_device *dev, void __user *useraddr)
 {
 	struct ethtool_gstrings gstrings;
 	u8 *data;
 	int ret;

 	if (copy_from_user(&gstrings, useraddr, sizeof(gstrings)))
 		return -EFAULT;

 	ret = __ethtool_get_sset_count(dev, gstrings.string_set);
 	if (ret < 0)
 		return ret;
 	if (ret > S32_MAX / ETH_GSTRING_LEN)
 		return -ENOMEM;
 	WARN_ON_ONCE(!ret);

-	gstrings.len = ret;
+	if (gstrings.len && gstrings.len != ret)
+		gstrings.len = 0;
+	else
+		gstrings.len = ret;

 	if (gstrings.len) {
 		data = vzalloc(array_size(gstrings.len, ETH_GSTRING_LEN));
 		if (!data)
 			return -ENOMEM;

 		__ethtool_get_strings(dev, gstrings.string_set, data);
 	} else {
 		data = NULL;
 	}

 	ret = -EFAULT;
 	if (copy_to_user(useraddr, &gstrings, sizeof(gstrings)))
 		goto out;
 	useraddr += sizeof(gstrings);
 	if (gstrings.len &&
 	    copy_to_user(useraddr, data,
 			 array_size(gstrings.len, ETH_GSTRING_LEN)))
 		goto out;
 	ret = 0;

 out:
 	vfree(data);
 	return ret;
 }


 static int ethtool_get_stats(struct net_device *dev, void __user *useraddr)
 {
 	struct ethtool_stats stats;
 	const struct ethtool_ops *ops = dev->ethtool_ops;
 	u64 *data;
 	int ret, n_stats;

 	if (!ops->get_ethtool_stats || !ops->get_sset_count)
 		return -EOPNOTSUPP;

 	n_stats = ops->get_sset_count(dev, ETH_SS_STATS);
 	if (n_stats < 0)
 		return n_stats;
 	if (n_stats > S32_MAX / sizeof(u64))
 		return -ENOMEM;
 	WARN_ON_ONCE(!n_stats);
 	if (copy_from_user(&stats, useraddr, sizeof(stats)))
 		return -EFAULT;

-	stats.n_stats = n_stats;
+	if (stats.n_stats && stats.n_stats != n_stats)
+		stats.n_stats = 0;
+	else
+		stats.n_stats = n_stats;

-	if (n_stats) {
-		data = vzalloc(array_size(n_stats, sizeof(u64)));
+	if (stats.n_stats) {
+		data = vzalloc(array_size(stats.n_stats, sizeof(u64)));
 		if (!data)
 			return -ENOMEM;
 		ops->get_ethtool_stats(dev, &stats, data);
 	} else {
 		data = NULL;
 	}

 	ret = -EFAULT;
 	if (copy_to_user(useraddr, &stats, sizeof(stats)))
 		goto out;
 	useraddr += sizeof(stats);
-	if (n_stats && copy_to_user(useraddr, data, array_size(n_stats, sizeof(u64))))
+	if (stats.n_stats &&
+	    copy_to_user(useraddr, data,
+			 array_size(stats.n_stats, sizeof(u64))))
 		goto out;
 	ret = 0;

  out:
 	vfree(data);
 	return ret;
 }


 static int ethtool_get_phy_stats_phydev(struct phy_device *phydev,
 					 struct ethtool_stats *stats,
 					 u64 **data)
  {
 	const struct ethtool_phy_ops *phy_ops = ethtool_phy_ops;
 	int n_stats, ret;

 	if (!phy_ops || !phy_ops->get_sset_count || !phy_ops->get_stats)
 		return -EOPNOTSUPP;

 	n_stats = phy_ops->get_sset_count(phydev);
+	if (stats->n_stats && stats->n_stats != n_stats) {
+		stats->n_stats = 0;
+		return 0;
+	}

 	ret = ethtool_vzalloc_stats_array(n_stats, data);
 	if (ret)
 		return ret;

 	stats->n_stats = n_stats;
 	return phy_ops->get_stats(phydev, stats, *data);
 }

 static int ethtool_get_phy_stats_ethtool(struct net_device *dev,
 					  struct ethtool_stats *stats,
 					  u64 **data)
 {
 	const struct ethtool_ops *ops = dev->ethtool_ops;
 	int n_stats, ret;

 	if (!ops || !ops->get_sset_count || !ops->get_ethtool_phy_stats)
 		return -EOPNOTSUPP;

 	n_stats = ops->get_sset_count(dev, ETH_SS_PHY_STATS);
+	if (stats->n_stats && stats->n_stats != n_stats) {
+		stats->n_stats = 0;
+		return 0;
+	}

 	ret = ethtool_vzalloc_stats_array(n_stats, data);
 	if (ret)
 		return ret;

 	stats->n_stats = n_stats;
 	ops->get_ethtool_phy_stats(dev, stats, *data);

 	return 0;
 }

 static int ethtool_get_phy_stats(struct net_device *dev, void __user *useraddr)
 {
 	struct phy_device *phydev = dev->phydev;
 	struct ethtool_stats stats;
 	u64 *data = NULL;
 	int ret = -EOPNOTSUPP;

 	if (copy_from_user(&stats, useraddr, sizeof(stats)))
 		return -EFAULT;

 	if (phydev)
 		ret = ethtool_get_phy_stats_phydev(phydev, &stats, &data);

 	if (ret == -EOPNOTSUPP)
 		ret = ethtool_get_phy_stats_ethtool(dev, &stats, &data);

 	if (ret)
 		goto out;

 	if (copy_to_user(useraddr, &stats, sizeof(stats))) {
 		ret = -EFAULT;
 		goto out;
 	}

 	useraddr += sizeof(stats);
-	if (copy_to_user(useraddr, data, array_size(stats.n_stats, sizeof(u64))))
+	if (stats.n_stats &&
+	    copy_to_user(useraddr, data,
+			 array_size(stats.n_stats, sizeof(u64))))
 		ret = -EFAULT;

  out:
 	vfree(data);
 	return ret;
 }



